// Generated by bynk — do not edit by hand.
// bynk.crypto binding for the `browser` platform: Web Crypto (`crypto.subtle`)
// and nothing else. No third-party crypto runs here and nothing is polyfilled.
//
// R-16 (security review): keys are imported non-extractable; no error or log
// line carries key material (every failure reason below is a fixed string); the
// algorithm parameters are fixed by the enums, never caller-chosen; a platform
// without `crypto.subtle` fails loudly.
import { CryptoError } from "./crypto.js";
import type { Crypto, Digest, Signature, SigningKey, VerifyKey } from "./crypto.js";
import type { Secret } from "../bynk.js";
import { Err, Ok, type Result } from "../runtime.js";

// The shared body: identical in the three platform bindings (`bynk-std`'s drift
// test compares them) apart from the marked region below.

type Bytes = globalThis.Uint8Array;

// Web Crypto exists only in a secure context in a browser (R14.5); a platform
// without it is a loud failure, never a silent degrade.
function subtle(): SubtleCrypto {
  const s = (globalThis as { crypto?: { subtle?: SubtleCrypto } }).crypto?.subtle;
  if (!s) {
    throw new Error(
      "bynk.crypto needs Web Crypto (crypto.subtle), which this environment does not provide — a browser exposes it only in a secure context (HTTPS or localhost)",
    );
  }
  return s;
}

function hashName(algorithm: Digest): string {
  switch (algorithm.tag) {
    case "Sha256":
      return "SHA-256";
    case "Sha384":
      return "SHA-384";
    case "Sha512":
      return "SHA-512";
  }
}

// What a key import can fail with, by the DOMException name Web Crypto uses. The
// reason is a fixed string: never the platform's message, which may echo input.
function importError(e: unknown, algorithm: string, what: string): CryptoError {
  const name = (e as { name?: unknown } | null)?.name;
  if (name === "NotSupportedError") {
    return CryptoError.UnsupportedAlgorithm(algorithm);
  }
  return CryptoError.InvalidKey(`not a valid ${what} for ${algorithm}`);
}

// The import parameters of a signature algorithm: fixed, so a caller cannot pick
// a curve or hash outside the enum.
function importParams(algorithm: Signature): { name: string; namedCurve?: string; hash?: string } {
  switch (algorithm.tag) {
    case "Ed25519":
      return { name: "Ed25519" };
    case "EcdsaP256Sha256":
      return { name: "ECDSA", namedCurve: "P-256" };
    case "RsaPkcs1Sha256":
      return { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" };
  }
}

function algorithmName(algorithm: Signature): string {
  return importParams(algorithm).name;
}

// The sign/verify parameters of an imported key, from the algorithm it was
// imported for.
function signParams(key: CryptoKey): { name: string; hash?: string } {
  const name = key.algorithm.name;
  return name === "ECDSA" ? { name, hash: "SHA-256" } : { name };
}

function asSigning(key: CryptoKey): SigningKey {
  return key as unknown as SigningKey;
}

function asVerify(key: CryptoKey): VerifyKey {
  return key as unknown as VerifyKey;
}

function asCryptoKey(key: SigningKey | VerifyKey): CryptoKey {
  return key as unknown as CryptoKey;
}

// Ed25519 public keys are 32 raw bytes or SPKI; the rest are SPKI.
const ED25519_RAW_LENGTH = 32;

// The constant-time comparison of two equal-length byte strings, by the platform
// primitive where there is one, else the double-HMAC comparison: HMAC both
// values under a fresh random key and compare the results with `subtle.verify`,
// whose comparison is constant-time. The length is not a secret, so unequal
// lengths are unequal at once.
async function constantTimeEqual(a: Bytes, b: Bytes): Promise<boolean> {
  if (a.length !== b.length) {
    return false;
  }
  const s = subtle();
  const native = platformTimingSafeEqual();
  if (native) {
    return native(a, b);
  }
  const key = await s.generateKey({ name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
  const mac = await s.sign("HMAC", key, a as BufferSource);
  return s.verify("HMAC", key, mac, b as BufferSource);
}

// --- platform: constant-time comparison primitive ---------------------------
// A browser has no timing-safe primitive: the double-HMAC comparison is used.
function platformTimingSafeEqual(): ((a: Bytes, b: Bytes) => boolean) | undefined {
  return undefined;
}
// --- end platform ------------------------------------------------------------

// #4118: key derivation and password hashing, over `crypto.subtle` alone.
//
// HKDF-SHA-256 (RFC 5869): `deriveBits` with the key imported as raw HKDF key material. The output is
// at most 255 hash blocks, 8160 bytes for SHA-256.
const HKDF_MAX_LENGTH = 255 * 32;

// Password hashing is PBKDF2-HMAC-SHA-256 at an iteration count Bynk chooses (OWASP's current guidance
// for this algorithm), with a fresh 16-byte salt and a 32-byte hash. The count is written into each
// stored hash, so a later release can raise it and every older hash still verifies.
const PASSWORD_SCHEME = "pbkdf2-sha256";
const PASSWORD_ITERATIONS = 600000;
const PASSWORD_SALT_BYTES = 16;
const PASSWORD_HASH_BYTES = 32;
// What a stored hash may claim: a crafted `stored` cannot make `verifyPassword` spin for minutes.
const PASSWORD_MAX_ITERATIONS = 10000000;
const PASSWORD_MIN_SALT_BYTES = 8;
const PASSWORD_MAX_SALT_BYTES = 64;
const PASSWORD_MIN_HASH_BYTES = 16;
const PASSWORD_MAX_HASH_BYTES = 64;

function toBase64(bytes: Bytes): string {
  let binary = "";
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]!);
  return globalThis.btoa(binary).split("=").join("");
}

// Strict, unpadded standard base64; anything else is `undefined`.
function fromBase64(text: string): Bytes | undefined {
  if (!/^[A-Za-z0-9+/]+$/.test(text) || text.length % 4 === 1) return undefined;
  try {
    const binary = globalThis.atob(text + "=".repeat((4 - (text.length % 4)) % 4));
    const out = new globalThis.Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
    return out;
  } catch {
    return undefined;
  }
}

async function pbkdf2(password: string, salt: Bytes, iterations: number, length: number): Promise<Bytes> {
  const s = subtle();
  // NFC, so the same typed password always matches however the keyboard composed it.
  const text = new TextEncoder().encode(password.normalize("NFC"));
  const key = await s.importKey("raw", text as BufferSource, "PBKDF2", false, ["deriveBits"]);
  const bits = await s.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: salt as BufferSource, iterations }, key, length * 8);
  return new Uint8Array(bits);
}

type StoredPassword = { iterations: number; salt: Bytes; hash: Bytes };

// A stored hash in this format, or `undefined` for anything else: it is never a fault.
function parseStored(stored: string): StoredPassword | undefined {
  const parts = stored.split("$");
  if (parts.length !== 4 || parts[0] !== PASSWORD_SCHEME) return undefined;
  if (!/^[1-9][0-9]{0,9}$/.test(parts[1]!)) return undefined;
  const iterations = Number(parts[1]);
  if (iterations > PASSWORD_MAX_ITERATIONS) return undefined;
  const salt = fromBase64(parts[2]!);
  const hash = fromBase64(parts[3]!);
  if (!salt || !hash) return undefined;
  if (salt.length < PASSWORD_MIN_SALT_BYTES || salt.length > PASSWORD_MAX_SALT_BYTES) return undefined;
  if (hash.length < PASSWORD_MIN_HASH_BYTES || hash.length > PASSWORD_MAX_HASH_BYTES) return undefined;
  return { iterations, salt, hash };
}

export class CryptoProvider implements Crypto {
  async digest(algorithm: Digest, data: Bytes): Promise<Bytes> {
    return new Uint8Array(await subtle().digest(hashName(algorithm), data as BufferSource));
  }

  async hmac(algorithm: Digest, key: Bytes, data: Bytes): Promise<Bytes> {
    if (key.length === 0) {
      throw new Error("Crypto.hmac requires a non-empty key");
    }
    const s = subtle();
    const k = await s.importKey("raw", key as BufferSource, { name: "HMAC", hash: hashName(algorithm) }, false, ["sign"]);
    return new Uint8Array(await s.sign("HMAC", k, data as BufferSource));
  }

  async verifyHmac(algorithm: Digest, key: Bytes, data: Bytes, mac: Bytes): Promise<boolean> {
    if (key.length === 0) {
      throw new Error("Crypto.verifyHmac requires a non-empty key");
    }
    const s = subtle();
    const k = await s.importKey("raw", key as BufferSource, { name: "HMAC", hash: hashName(algorithm) }, false, ["verify"]);
    return s.verify("HMAC", k, mac as BufferSource, data as BufferSource);
  }

  async equal(a: Bytes, b: Bytes): Promise<boolean> {
    return constantTimeEqual(a, b);
  }

  async importSigningKey(algorithm: Signature, pkcs8: Bytes): Promise<Result<SigningKey, CryptoError>> {
    const s = subtle();
    try {
      const key = await s.importKey("pkcs8", pkcs8 as BufferSource, importParams(algorithm), false, ["sign"]);
      return Ok(asSigning(key));
    } catch (e) {
      return Err(importError(e, algorithmName(algorithm), "PKCS#8 private key"));
    }
  }

  // #4111: the PKCS#8 key arrives as a `Secret` holding its base64, so the text never has to be a
  // `String` in the program. It is revealed here, decoded and handed on; a failure names no text.
  async importSigningKeyFromSecret(algorithm: Signature, secret: Secret): Promise<Result<SigningKey, CryptoError>> {
    let pkcs8: Bytes;
    try {
      const binary = globalThis.atob(secret.reveal());
      pkcs8 = new globalThis.Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) pkcs8[i] = binary.charCodeAt(i);
    } catch {
      return Err(CryptoError.InvalidKey("the secret is not base64"));
    }
    return this.importSigningKey(algorithm, pkcs8);
  }

  async importVerifyKey(algorithm: Signature, key: Bytes): Promise<Result<VerifyKey, CryptoError>> {
    const s = subtle();
    const raw = algorithm.tag === "Ed25519" && key.length === ED25519_RAW_LENGTH;
    try {
      const imported = await s.importKey(
        raw ? "raw" : "spki",
        key as BufferSource,
        importParams(algorithm),
        false,
        ["verify"],
      );
      return Ok(asVerify(imported));
    } catch (e) {
      return Err(importError(e, algorithmName(algorithm), raw ? "raw public key" : "SPKI public key"));
    }
  }

  async importVerifyJwk(jwk: string): Promise<Result<VerifyKey, CryptoError>> {
    const s = subtle();
    let parsed: { kty?: unknown; crv?: unknown; d?: unknown };
    try {
      const value: unknown = JSON.parse(jwk);
      if (typeof value !== "object" || value === null || Array.isArray(value)) {
        throw new Error("not an object");
      }
      parsed = value;
    } catch {
      return Err(CryptoError.InvalidKey("not a JSON object (JWK)"));
    }
    // The algorithm comes from the key's own `kty` and `crv`; a private JWK is
    // refused outright (it is for `importSigningKey`, which takes PKCS#8).
    if (parsed.d !== undefined) {
      return Err(CryptoError.InvalidKey("a JWK with private parameters is not a verify key"));
    }
    let params: { name: string; namedCurve?: string; hash?: string };
    if (parsed.kty === "OKP" && parsed.crv === "Ed25519") {
      params = { name: "Ed25519" };
    } else if (parsed.kty === "EC" && parsed.crv === "P-256") {
      params = { name: "ECDSA", namedCurve: "P-256" };
    } else if (parsed.kty === "RSA") {
      params = { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" };
    } else {
      return Err(CryptoError.UnsupportedAlgorithm("JWK kty/crv"));
    }
    try {
      const key = await s.importKey("jwk", parsed as JsonWebKey, params, false, ["verify"]);
      return Ok(asVerify(key));
    } catch (e) {
      return Err(importError(e, params.name, "JWK public key"));
    }
  }

  async sign(key: SigningKey, data: Bytes): Promise<Bytes> {
    const k = asCryptoKey(key);
    return new Uint8Array(await subtle().sign(signParams(k), k, data as BufferSource));
  }

  async verify(key: VerifyKey, data: Bytes, signature: Bytes): Promise<boolean> {
    const k = asCryptoKey(key);
    const s = subtle();
    try {
      return await s.verify(signParams(k), k, signature as BufferSource, data as BufferSource);
    } catch {
      // A signature the algorithm cannot even parse does not verify.
      return false;
    }
  }

  async deriveKey(secret: Bytes, salt: Bytes, info: Bytes, length: number): Promise<Bytes> {
    if (secret.length === 0) {
      throw new Error("Crypto.deriveKey requires a non-empty secret");
    }
    if (!Number.isInteger(length) || length < 1 || length > HKDF_MAX_LENGTH) {
      throw new Error(`Crypto.deriveKey length must be a whole number from 1 to ${HKDF_MAX_LENGTH}`);
    }
    const s = subtle();
    const k = await s.importKey("raw", secret as BufferSource, "HKDF", false, ["deriveBits"]);
    const bits = await s.deriveBits(
      { name: "HKDF", hash: "SHA-256", salt: salt as BufferSource, info: info as BufferSource },
      k,
      length * 8,
    );
    return new Uint8Array(bits);
  }

  async hashPassword(password: string): Promise<string> {
    const salt = globalThis.crypto.getRandomValues(new Uint8Array(PASSWORD_SALT_BYTES));
    const hash = await pbkdf2(password, salt, PASSWORD_ITERATIONS, PASSWORD_HASH_BYTES);
    return `${PASSWORD_SCHEME}$${PASSWORD_ITERATIONS}$${toBase64(salt)}$${toBase64(hash)}`;
  }

  async verifyPassword(password: string, stored: string): Promise<boolean> {
    const parsed = parseStored(stored);
    if (!parsed) {
      return false;
    }
    // A count this platform's Web Crypto refuses is a hash this platform cannot check: `false`, never a fault.
    let candidate: Bytes;
    try {
      candidate = await pbkdf2(password, parsed.salt, parsed.iterations, parsed.hash.length);
    } catch (e) {
      // Not a silent lockout: say which hash and why, naming no password and no platform text.
      const name = (e as { name?: unknown } | null)?.name;
      globalThis.console?.warn(
        `bynk.crypto: verifyPassword could not check a stored hash: this platform's Web Crypto refused PBKDF2 at ${parsed.iterations} iterations (${typeof name === "string" ? name : "error"})`,
      );
      return false;
    }
    return constantTimeEqual(candidate, parsed.hash);
  }

  async needsRehash(stored: string): Promise<boolean> {
    const parsed = parseStored(stored);
    return (
      !parsed ||
      parsed.iterations < PASSWORD_ITERATIONS ||
      parsed.salt.length < PASSWORD_SALT_BYTES ||
      parsed.hash.length < PASSWORD_HASH_BYTES
    );
  }
}
